chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.create({id:"jobFinder",title:"Job Finder",contexts:["selection"]}),chrome.contextMenus.create({id:"goToCompany",title:"Go To Company",parentId:"jobFinder",contexts:["selection"]}),chrome.contextMenus.create({id:"findPerson",title:"Find Person",parentId:"jobFinder",contexts:["selection"]})});chrome.contextMenus.onClicked.addListener(e=>{const t=e.selectionText;e.menuItemId==="goToCompany"?chrome.tabs.create({url:`https://www.linkedin.com/search/results/companies/?keywords=${encodeURIComponent(t)}`}):e.menuItemId==="findPerson"&&chrome.tabs.create({url:`https://www.linkedin.com/search/results/people/?keywords=${encodeURIComponent(t)}`})});chrome.action.onClicked.addListener(e=>{chrome.sidePanel.open({windowId:e.windowId})});chrome.runtime.onMessage.addListener((e,t,n)=>{if(e.action==="fetchPageText")return o(e.url).then(n).catch(r=>{n({error:r.message})}),!0});async function o(e){const t=await fetch(e);if(!t.ok)throw new Error(`Fetch failed: ${t.status} ${t.statusText}`);const n=await t.text();return{text:i(n),title:c(n)}}function c(e){const t=e.match(/<title[^>]*>([^<]*)<\/title>/i);return t?t[1].trim():""}function i(e){return e.replace(/<script[\s\S]*?<\/script>/gi," ").replace(/<style[\s\S]*?<\/style>/gi," ").replace(/<!--[\s\S]*?-->/g," ").replace(/<(br|\/p|\/div|\/li|\/h[1-6])[^>]*>/gi,`
`).replace(/<[^>]+>/g," ").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/[ \t]+/g," ").replace(/\n\s*\n+/g,`
`).trim()}
